fn to_toggle_case(str1: &Vec<char>) -> Vec<char> {
    str1.iter()
        .map(|&ch| {
            if ('a'..='z').contains(&ch) {
                // lowercase to uppercase
                ((ch as u8) - b'a' + b'A') as char
            } else if ('A'..='Z').contains(&ch) {
                // uppercase to lowercase
                ((ch as u8) - b'A' + b'a') as char
            } else {
                // all other chars unchanged
                ch
            }
        })
        .collect()
}